Method.Implementation:
	Set tSC=$$$OK

	//Journal
	if (..JournalIncomingData) {
		Set tSC=..JournalData(pInput)
	}
	Set tSC=..resolveAndIndex(pInput) Quit:$$$ISERR(tSC) tSC

	For iTarget=1:1:$L(..TargetConfigNames, ",") 
        { 
            Set tOneTarget=$ZStrip($P(..TargetConfigNames,",",iTarget),"<>W")  
            Continue:""=tOneTarget

            $$$TRACE("Send msg to " _ tOneTarget)	
	    	Set tSC1=..SendRequestAsync(tOneTarget,pInput)  
	    	Set:$$$ISERR(tSC1) tSC=$$$ADDSC(tSC,tSC1)
		}


	Quit tSC

Do ##super(.pArray,pItem)
If pItem.GetModifiedSetting("TargetConfigNames",.tValue) {
	For i=1:1:$L(tValue,",") { Set tOne=$ZStrip($P(tValue,",",i),"<>W")  Continue:""=tOne  Set pArray(tOne)="" }
}
